python3 -c 'import os,re; fs=[]
for root,ds,ns in os.walk("."):
  if root.startswith("./.git"): ds[:]=[]; continue
  for n in ns:
   if n.endswith(".go") and not n.endswith("_test.go"): fs.append(os.path.join(root,n))
defs=[]
for f in fs:
 s=open(f).read()
 if f.startswith("./internal/"):
  for m in re.finditer(r"^func\s+(?:\([^\n]*\)\s+)?([A-Za-z_]\w*)\s*\(",s,re.M): defs.append((m.group(1),f,m.start()))
for name,f,pos in sorted(defs,key=lambda d:sum(len(re.findall(r"(?<!func\s)\b"+re.escape(d[0])+r"\s*\(",open(x).read())) for x in fs),reverse=True)[:20]:
 c=sum(len(re.findall(r"(?<!func\s)\b"+re.escape(name)+r"\s*\(",open(x).read())) for x in fs)-1
 print(c,name,f)'
